<?php
/** Plugin Name: TEMP PS S1728md read-only: FBT v1.7 simuliacija (nauja klase pervadinta, be hooku, sarasai per pre_option) */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1728md'])) return; $r=['v'=>'S1728md']; @set_time_limit(170);
  try{
    $L=json_decode(base64_decode(''),true);
    add_filter('pre_option_ps_fbt_skanestai',function() use($L){ return $L; });
    if(!class_exists('Petshop_FBT_S1728')) eval(gzdecode(base64_decode('')));
    $rc=new ReflectionClass('Petshop_FBT_S1728'); $o=$rc->newInstanceWithoutConstructor();
    $gc=$rc->getMethod('get_companions'); $gc->setAccessible(true);
    $sc=$rc->getMethod('suggest_core'); $sc->setAccessible(true);
    $nm=function($id){ $p=wc_get_product($id); return $p? html_entity_decode($p->get_name()).' · '.wc_format_decimal($p->get_price(),2).' €':'?'; };
    foreach([18587, 18590, 17978, 18560, 19582, 19496, 19590, 18599, 18369, 19411, 19417, 19598, 19396, 19446, 19570, 19578, 19562, 19488, 18149, 18018, 18366, 19545, 19387, 19449, 19692, 18154, 19358, 19594, 19399, 19405, 19425, 19440, 19708, 18372, 16942, 19479, 19355, 17493, 18572, 19672, 19414, 19553, 19620, 19504, 16936, 19586, 19685, 19500, 19534, 19613, 33370, 23880, 14652, 14619, 18623, 16463, 16460, 14804, 14805, 14678] as $pid){ $fo=$o->food_offer($pid,1); $g=$gc->invoke($o,$pid);
      $r['rows'][]=['pid'=>$pid,'sp'=>$o->food_species($pid),'wh'=>$fo['wh'],'zymos'=>implode('; ',$fo['zymos']),'zaislas'=>$fo['zaislas'],'kodel'=>$fo['kodel'],'rodytu'=>array_map(function($i)use($fo,$nm){return ($fo['zaislas']?'🧸 ':'').$nm($i);},$fo['ids']),'gc_sutampa'=>$g===$fo['ids']]; }
    // krepselio simuliacijos
    foreach([[18587],[18587,17978],[17978,19033],[18590,16305],[18623,17978],[36003]] as $set){ $lines=array_map(function($i){return['id'=>$i,'qty'=>1];},$set); $res=$sc->invoke($o,$lines,4,true);
      $r['krepselis'][]=['set'=>$set,'items'=>array_map(function($x)use($nm){return $x['id'].' '.$nm($x['id']).' | charge '.$x['charge'].' pct '.$x['pct'].' anchor '.$x['anchor'];},$res['items']),'maistas'=>$res['debug']['maistas']??[],'atmesta'=>array_slice($res['debug']['atmesta'],0,8)]; }
    // 3 maišai Exclusion (AV 2) -> turi būti VF
    $r['excl_3vnt']=['wh'=>$o->food_wh(18587,3)];
    if(method_exists('Petshop_AV_Source','ar_misrus')){ $rf=new ReflectionMethod('Petshop_AV_Source','ar_misrus'); $s=file($rf->getFileName()); $r['ar_misrus']=implode('',array_slice($s,$rf->getStartLine()-1,$rf->getEndLine()-$rf->getStartLine()+1)); }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getFile().':'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE); exit;
}, 1);
